<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),comparison=ref('single')
const labels=['Speed','Quality','Reach','Support','Cost','Trust']
const values=computed(()=>dataset.value==='A'?[35,48,41,61,56,74]:dataset.value==='B'?[42,36,55,48,72,64]:[0,0,0,0,0,0])
const reference=[60,60,60,60,60,60]
const point=(v:number,i:number)=>[160+Math.cos(i*Math.PI/3-Math.PI/2)*v*.8,120+Math.sin(i*Math.PI/3-Math.PI/2)*v*.8]
const polygon=(a:number[])=>a.map((v,i)=>point(v,i).join(',')).join(' ')
function reset(){dataset.value='A';state.value='ready';selected.value=0;comparison.value='single'}
</script>
<template>
<section class="rdusage-demo" aria-label="Local radar chart example"><p>Synthetic normalized scores, all higher-is-better, including Cost efficiency. Axis order is fixed. Polygon area is not an overall score.</p><div class="rdusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><label>Comparison<select v-model="comparison"><option value="single">Single profile</option><option value="reference">With reference</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="rdusage-legend"><span>Solid: Primary</span><span v-if="comparison==='reference'">Dashed: Reference 60 on every axis</span><span>Scale 0–100</span></div><svg :key="dataset+'-'+comparison" viewBox="0 0 320 250" role="img" aria-label="Six normalized score axes, fixed zero to one hundred, evenly spaced clockwise from up. Exact scores are below."><polygon v-for="tick in [25,50,75,100]" :key="tick" :points="polygon(Array(6).fill(tick))" class="rdusage-ring"/><line v-for="(_,i) in labels" :key="i" x1="160" y1="120" :x2="point(100,i)[0]" :y2="point(100,i)[1]" class="rdusage-ring"/><polygon v-if="comparison==='reference'" :points="polygon(reference)" class="rdusage-reference"/><polygon :points="polygon(values)" class="rdusage-primary"/><circle v-for="(v,i) in values" :key="i" class="rdusage-dot" :class="{selected:selected===i}" :cx="point(v,i)[0]" :cy="point(v,i)[1]" :r="selected===i?5:3"/><text v-for="(label,i) in labels" :key="label" :x="point(127,i)[0]" :y="point(127,i)[1]+4" text-anchor="middle">{{ label }}</text><text x="165" y="36">100</text><text x="164" y="121">0</text></svg><div role="group" aria-label="Select axis" class="rdusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}{{ selected===4?' efficiency':'' }}: Primary {{ values[selected] }} /100<span v-if="comparison==='reference'">; Reference {{ reference[selected] }} /100</span>.</p><table class="rdusage-data"><caption>Exact normalized scores, dataset {{ dataset }}</caption><thead><tr><th scope="col">Axis</th><th scope="col">Primary</th><th v-if="comparison==='reference'" scope="col">Reference</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}{{ i===4?' efficiency':'' }}</th><td>{{ values[i] }}</td><td v-if="comparison==='reference'">{{ reference[i] }}</td></tr></tbody></table></template><p v-else role="status" class="rdusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample profile in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.rdusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.rdusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.rdusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.rdusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.rdusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.rdusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.rdusage-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.rdusage-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:rdusage-in .2s ease-out}.rdusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.rdusage-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.rdusage-pair{opacity:.65}.rdusage-pair.selected{opacity:1}.rdusage-pair.selected text{font-weight:700;fill:var(--vp-c-text-1)}.rdusage-gap{stroke:var(--vp-c-brand-1);stroke-width:2}.rdusage-pair.selected .rdusage-gap{stroke-width:4}.rdusage-primary{fill:var(--vp-c-brand-1);fill-opacity:.18;stroke:var(--vp-c-brand-1);stroke-width:2}.rdusage-reference{fill:none;stroke:var(--vp-c-text-1);stroke-width:2;stroke-dasharray:5 4}.rdusage-dot{fill:var(--vp-c-brand-1)}.rdusage-dot.selected{stroke:var(--vp-c-text-1);stroke-width:2}.rdusage-ring{fill:none;stroke:var(--vp-c-divider);stroke-dasharray:3 3}.rdusage-zero{fill:var(--vp-c-text-1)}.rdusage-choices{display:flex;gap:6px;flex-wrap:wrap}.rdusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.rdusage-data{display:table!important;width:100%;font-size:12px}.rdusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.rdusage-data :is(td,th){padding:6px!important}.rdusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes rdusage-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.rdusage-demo svg{animation:none}}
</style>
